#!/usr/bin/env python3
import argparse
import base64
import json
import os
import zlib

SPEC_B64 = ""

def main():
    parser = argparse.ArgumentParser(description="Generate OpenBLAS wrapper sources")
    parser.add_argument("--out_dir", required=True, help="Directory to output generated files")
    args = parser.parse_args()

    raw = zlib.decompress(base64.b64decode(SPEC_B64))
    spec = json.loads(raw)

    for out_rel, defs, inc in spec:
        target_path = os.path.join(args.out_dir, out_rel)
        os.makedirs(os.path.dirname(target_path), exist_ok=True)
        content = []
        for d in defs:
            content.append(f"#define {d}\n")
        content.append(f"#include \"{inc}\"\n")
        with open(target_path, "w") as out_f:
            out_f.writelines(content)

if __name__ == "__main__":
    main()
